computed<CoarIconSize>(() => {
    const sizeMap: Record<CoarNumberInputSize, CoarIconSize> = {
      xs: 'xs',
      sm: 'xs',
      md: 'sm',
      lg: 'md',
    };
    return sizeMap[this.size()];
