import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  ElementRef,
  input,
  model,
  output,
  computed,
  inject,
  viewChild,
  TemplateRef,
} from '@angular/core';

import { FormsModule } from '@angular/forms';
import { CoarIconComponent } from '../coar-icon/coar-icon.component';
import { CoarScrollbarDirective } from '../coar-scrollbar/coar-scrollbar.directive';
import { coarProvideValueAccessor } from '../forms/coar-control-value-accessor';
import { CoarSelectBase, CoarSelectSize } from './coar-select-base';
import { CoarSelectOption } from './coar-select-option.interface';
import { createOverlayBuilder, type OverlayRef, type Placement } from '@cocoar/ui-overlay';

export type { CoarSelectSize };

/**
 * Single-select dropdown component.
 *
 * Allows selecting one option from a list with keyboard navigation,
 * search/filter support, and full forms integration.
 *
 * @example
 * ```html
 * <coar-single-select
 *   label="Country"
 *   [options]="countries"
 *   [(value)]="selectedCountry"
 *   placeholder="Select a country"
 * />
 * ```
 */
@Component({
  selector: 'coar-single-select',
  standalone: true,
  imports: [FormsModule, CoarIconComponent, CoarScrollbarDirective],
  templateUrl: './coar-single-select.component.html',
  styleUrl: './coar-single-select.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [coarProvideValueAccessor(() => CoarSingleSelectComponent)],
  host: {
    '[class.coar-single-select--xs]': 'size() === "xs"',
    '[class.coar-single-select--sm]': 'size() === "sm"',
    '[class.coar-single-select--md]': 'size() === "md"',
    '[class.coar-single-select--lg]': 'size() === "lg"',
    '[class.coar-single-select--disabled]': 'isDisabled()',
    '[class.coar-single-select--readonly]': 'readonly()',
    '[class.coar-single-select--error]': 'hasError()',
    '[class.coar-single-select--open]': 'isOpen()',
  },
})
export class CoarSingleSelectComponent<T = unknown> extends CoarSelectBase<T | null> {
  private readonly overlayBuilder = createOverlayBuilder();
  private readonly destroyRefLocal = inject(DestroyRef);

  private readonly triggerRef = viewChild<ElementRef<HTMLElement>>('trigger');
  private readonly dropdownTemplateRef = viewChild<TemplateRef<unknown>>('dropdownTemplate');

  private overlayRef: OverlayRef | null = null;

  /** Current selected value (two-way bindable with [(value)]) */
  value = model<T | null>(null);

  /** Whether to show a clear button when a value is selected */
  clearable = input<boolean, unknown>(true, {
    transform: (v: unknown) => (v === '' ? true : Boolean(v)),
  });

  /** Emits when the selected value changes */
  valueChange = output<T | null>();

  /** CSS selector for highlighted option (used by base class scrollToHighlighted) */
  protected get highlightedOptionSelector(): string {
    return '.coar-select-option--highlighted';
  }

  /** The currently selected option object */
  protected selectedOption = computed(() => {
    const currentValue = this.value();
    if (currentValue === null || currentValue === undefined) return null;
    const compare = this.compareWith() ?? ((a: unknown, b: unknown) => a === b);
    return this.options().find((opt) => compare(opt.value, currentValue)) ?? null;
  });

  /** Whether to show the clear button */
  protected showClearButton = computed(() => {
    return this.clearable() && this.value() !== null && !this.isDisabled() && !this.readonly();
  });

  /** Display text for the current selection */
  getDisplayText(): string {
    const selected = this.selectedOption();
    return selected?.label ?? '';
  }

  /** Write value from forms API */
  writeValue(value: T | null): void {
    this.value.set(value);
  }

  /** Select an option by its value */
  selectOption(option: CoarSelectOption<T>): void {
    if (option.disabled || this.isDisabled() || this.readonly()) return;

    this.value.set(option.value);
    this.valueChange.emit(option.value);
    this.cvaOnChange(option.value);
    this.closeDropdown();
  }

  /** Select the currently highlighted option */
  protected selectHighlightedOption(): void {
    const options = this.filteredOptions();
    const index = this.highlightedIndex();

    if (index >= 0 && index < options.length) {
      const option = options[index] as CoarSelectOption<T>;
      if (!option.disabled) {
        this.selectOption(option);
      }
    }
  }

  /** Clear the current selection */
  protected clearSelection(event: Event): void {
    event.stopPropagation();
    this.value.set(null);
    this.valueChange.emit(null);
    this.cvaOnChange(null);
  }

  /** Check if an option is currently selected */
  protected isSelected(option: CoarSelectOption): boolean {
    const compare = this.compareWith() ?? ((a: unknown, b: unknown) => a === b);
    return compare(this.value(), option.value);
  }

  protected override shouldCloseOnOutsideClick(): boolean {
    // The dropdown panel is rendered via @cocoar/ui-overlay (attached to document.body),
    // so hostElement.contains(event.target) would treat clicks inside the panel as "outside".
    // We rely on overlay dismissal (outsideClick) instead.
    return false;
  }

  protected override openDropdown(): void {
    if (this.isDisabled() || this.readonly()) return;
    if (this.overlayRef) return;

    const trigger = this.triggerRef()?.nativeElement;
    const template = this.dropdownTemplateRef();
    if (!trigger || !template) return;

    const placement = this.resolvePlacement(trigger, this.estimatePanelHeight());
    this.dropdownPosition.set(placement === 'top' ? 'top' : 'bottom');

    this.isOpen.set(true);
    this.searchQuery.set('');
    this.highlightedIndex.set(-1);

    const ref = this.overlayBuilder
      .anchor({ kind: 'element', element: trigger })
      .position({ placement, offset: 4, flip: false, shift: false })
      .scroll({ strategy: 'reposition' })
      .dismiss({ outsideClick: true, escapeKey: true })
      .size({ mode: 'content', minWidth: 'anchor' })
      .fromTemplate(template)
      .open({});
    this.overlayRef = ref;

    ref.afterClosed$.subscribe(() => {
      if (this.overlayRef !== ref) return;
      this.overlayRef = null;
      this.isOpen.set(false);
      this.searchQuery.set('');
      this.highlightedIndex.set(-1);
    });

    this.destroyRefLocal.onDestroy(() => {
      ref.close();
    });

    setTimeout(() => {
      if (!this.isOpen()) return;

      if (this.searchable()) {
        this.searchInputRef()?.nativeElement.focus();
      }

      if (this.dropdownPosition() === 'top') {
        this.scrollbarRef()?.scrollToBottom();
      }
    });
  }

  protected override closeDropdown(): void {
    const ref = this.overlayRef;
    this.overlayRef = null;
    ref?.close();
    this.isOpen.set(false);
    this.searchQuery.set('');
    this.highlightedIndex.set(-1);
  }

  private resolvePlacement(trigger: HTMLElement, estimatedPanelHeight: number): Placement {
    const preference = this.dropdownPositionPreference();
    if (preference === 'top') return 'top';
    if (preference === 'bottom') return 'bottom';

    const viewportHeight = document.documentElement?.clientHeight || window.innerHeight;
    const rect = trigger.getBoundingClientRect();

    const spaceBelow = Math.max(0, viewportHeight - rect.bottom);
    const spaceAbove = Math.max(0, rect.top);

    if (spaceBelow < estimatedPanelHeight && spaceAbove > spaceBelow) return 'top';
    return 'bottom';
  }

  private estimatePanelHeight(): number {
    const maxListHeight = 240;
    const optionRowHeight = 36;
    const listPadding = 8;

    const optionCount = this.displayOptions().length;
    const listHeight = Math.min(maxListHeight, optionCount * optionRowHeight + listPadding);

    const searchHeight = this.searchable() ? 56 : 0;
    const chromeHeight = 2;

    return chromeHeight + searchHeight + listHeight;
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  input,
  TemplateRef,
  Type,
  viewChild,
  booleanAttribute,
} from '@angular/core';

/**
 * Loading strategy for tab content:
 * - 'lazy': Content is only rendered when tab is active (default)
 * - 'eager': Content is always rendered, hidden when inactive
 */
export type TabLoadingStrategy = 'eager' | 'lazy';

/**
 * Content type that can be passed to a tab.
 * Either a TemplateRef (from ng-template) or a Component class.
 */
export type TabContent = TemplateRef<unknown> | Type<unknown>;

/**
 * Individual tab definition for use within CoarTabGroup.
 *
 * The tab label is provided as content projected into the component.
 * This allows simple text, icons, badges, or any custom HTML.
 *
 * @example Simple text label
 * ```html
 * <coar-tab id="home" [content]="homeTemplate">Home</coar-tab>
 * ```
 *
 * @example With icon
 * ```html
 * <coar-tab id="settings" [content]="SettingsComponent">⚙️ Settings</coar-tab>
 * ```
 *
 * @example Rich label with badge
 * ```html
 * <coar-tab id="messages" [content]="messagesTemplate">
 *   Messages <span class="badge">5</span>
 * </coar-tab>
 * ```
 */
@Component({
  selector: 'coar-tab',
  standalone: true,
  template: `<ng-template #labelContent><ng-content /></ng-template>`,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CoarTabComponent {
  /** Unique identifier for the tab */
  id = input.required<string>();

  /** Whether the tab is disabled */
  disabled = input<boolean, unknown>(false, { transform: booleanAttribute });

  /**
   * The content to display in the tab panel.
   * Can be either a TemplateRef (from ng-template) or a Component class.
   */
  content = input.required<TabContent>();

  /**
   * Inputs to pass when content is a Component.
   * Ignored when content is a TemplateRef.
   */
  contentInputs = input<Record<string, unknown>>({});

  /**
   * Loading strategy for the tab content.
   * - 'lazy' (default): Content is only rendered when tab becomes active
   * - 'eager': Content is always rendered, just hidden when inactive
   */
  loadingStrategy = input<TabLoadingStrategy>('lazy');

  /** Template reference for the projected label content */
  labelTemplate = viewChild.required<TemplateRef<unknown>>('labelContent');

  /**
   * Whether the content is a Component (vs a TemplateRef)
   */
  get isComponent(): boolean {
    const c = this.content();
    return typeof c === 'function';
  }

  /**
   * Get content as TemplateRef (returns null if it's a component)
   */
  get templateContent(): TemplateRef<unknown> | null {
    const c = this.content();
    return typeof c === 'function' ? null : c;
  }

  /**
   * Get content as Component type (returns null if it's a template)
   */
  get componentContent(): Type<unknown> | null {
    const c = this.content();
    return typeof c === 'function' ? c : null;
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  contentChildren,
  input,
  output,
  signal,
  effect,
  AfterContentInit,
} from '@angular/core';
import { CommonModule, NgComponentOutlet } from '@angular/common';
import { CoarTabComponent } from './coar-tab.component';

@Component({
  selector: 'coar-tab-group',
  standalone: true,
  imports: [CommonModule, NgComponentOutlet],
  templateUrl: './coar-tab-group.component.html',
  styleUrl: './coar-tab-group.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CoarTabGroupComponent implements AfterContentInit {
  /** The currently active tab id */
  activeTab = input<string>('');

  /** Emits when the active tab changes */
  activeTabChange = output<string>();

  /** All tab components projected into this group */
  tabs = contentChildren(CoarTabComponent);

  /** Internal active tab state */
  protected internalActiveTab = signal<string>('');

  constructor() {
    effect(() => {
      const externalTab = this.activeTab();
      if (externalTab) {
        this.internalActiveTab.set(externalTab);
      }
    });
  }

  ngAfterContentInit(): void {
    if (!this.internalActiveTab() && this.tabs().length > 0) {
      const firstTabId = this.tabs()[0].id();
      this.internalActiveTab.set(firstTabId);
    }
  }

  /** Check if a tab is currently active */
  isActive(tabId: string): boolean {
    const activeId = this.internalActiveTab();
    if (activeId) {
      return activeId === tabId;
    }
    return this.tabs()[0]?.id() === tabId;
  }

  /**
   * Determines whether the content of a tab should be rendered.
   * - For 'eager' strategy: always render (content stays in DOM)
   * - For 'lazy' strategy: only render when active
   */
  shouldRenderContent(tab: CoarTabComponent): boolean {
    if (tab.loadingStrategy() === 'eager') {
      return true;
    }
    // Default is lazy: only render when active
    return this.isActive(tab.id());
  }

  /** Select a tab by its id */
  selectTab(tabId: string): void {
    const tab = this.tabs().find((t) => t.id() === tabId);
    if (tab && !tab.disabled()) {
      this.internalActiveTab.set(tabId);
      this.activeTabChange.emit(tabId);
    }
  }

  /** Handle keyboard navigation */
  onKeydown(event: KeyboardEvent, currentTabId: string): void {
    const tabsArray = this.tabs().filter((t) => !t.disabled());
    const currentIndex = tabsArray.findIndex((t) => t.id() === currentTabId);

    let newIndex = currentIndex;

    switch (event.key) {
      case 'ArrowLeft':
        newIndex = currentIndex > 0 ? currentIndex - 1 : tabsArray.length - 1;
        event.preventDefault();
        break;
      case 'ArrowRight':
        newIndex = currentIndex < tabsArray.length - 1 ? currentIndex + 1 : 0;
        event.preventDefault();
        break;
      case 'Home':
        newIndex = 0;
        event.preventDefault();
        break;
      case 'End':
        newIndex = tabsArray.length - 1;
        event.preventDefault();
        break;
      default:
        return;
    }

    if (newIndex !== currentIndex) {
      const newTab = tabsArray[newIndex];
      this.selectTab(newTab.id());
      const tabButton = document.querySelector(`[data-tab-id="${newTab.id()}"]`) as HTMLElement;
      tabButton?.focus();
    }
  }
}

import { Component, input, ChangeDetectionStrategy, booleanAttribute } from '@angular/core';

export type CoarTableVariant = 'default' | 'plain' | 'bordered';

/**
 * A simple table component that provides consistent styling.
 *
 * Default styling uses alternating row colors (zebra stripes) for readability.
 * Use 'plain' variant for no stripes, or 'bordered' for full cell borders.
 *
 * Usage:
 * ```html
 * <coar-table>
 *   <thead>
 *     <tr>
 *       <th>Property</th>
 *       <th>Type</th>
 *     </tr>
 *   </thead>
 *   <tbody>
 *     <tr>
 *       <td><code>name</code></td>
 *       <td><code>string</code></td>
 *     </tr>
 *   </tbody>
 * </coar-table>
 * ```
 */
@Component({
  selector: 'coar-table',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="coar-table-wrapper">
      <table class="coar-table">
